from collections import Counter
def transform(g):
    H,W=len(g),len(g[0])
    bg=Counter(c for r in g for c in r).most_common(1)[0][0]
    out=[r[:] for r in g]
    seen=[[False]*W for _ in range(H)]
    for i in range(H):
        for j in range(W):
            if seen[i][j] or g[i][j]==bg: continue
            # BFS component
            stack=[(i,j)]; comp=[]
            seen[i][j]=True
            while stack:
                y,x=stack.pop(); comp.append((y,x))
                for dy,dx in((1,0),(-1,0),(0,1),(0,-1)):
                    ny,nx=y+dy,x+dx
                    if 0<=ny<H and 0<=nx<W and not seen[ny][nx] and g[ny][nx]!=bg:
                        seen[ny][nx]=True; stack.append((ny,nx))
            col=Counter(g[y][x] for y,x in comp).most_common(1)[0][0]
            rows=[y for y,x in comp]; cols=[x for y,x in comp]
            r0,r1,c0,c1=min(rows),max(rows),min(cols),max(cols)
            rcnt=[sum(1 for y,x in comp if y==r and g[y][x]==col) for r in range(r0,r1+1)]
            ccnt=[sum(1 for y,x in comp if x==c and g[y][x]==col) for c in range(c0,c1+1)]
            # rect rows/cols: those with count>=2 (col is solid-ish)
            if len(comp)>=6:
                good_r={r0+k for k,n in enumerate(rcnt) if n>=2}
                good_c={c0+k for k,n in enumerate(ccnt) if n>=2}
                for y in good_r:
                    for x in good_c:
                        out[y][x]=col
            else:
                for y,x in comp: out[y][x]=bg
    return out
